// SUPERSEDED 2026-08-11 (#749, migrations/2026-08-11-fleet-baseline-task): the lever is
// now a `manual`-frequency sheepdog TASK, the stub this record materializes is deleted
// from canon, and this record is a permanent no-op by construction — a missing template
// is a skip (applyMaterializations), and the successor record removes the copies this
// one installed. Kept, like every record, as the durable history of the shape.
//
// The sheepdog pack's fleet-baseline WORKFLOW lives in the pack
// (packs/sheepdog/stubs/workflows/fleet-baseline.yml) and RUNS from the enforcer repo's
// own .github/ — GitHub reads workflows only from a repo's own .github/, never from the
// shared mount. So the enforcer hosts a MANAGED copy: the pack owns the content, the
// repo owns the file. (The logic the workflow runs is NOT vendored here; it stays in the
// mount at .claudinite/shared/packs/sheepdog/fleet-baseline/, which is why this record
// materializes exactly one file.)
//
// HOW IT LANDS, since a workflow file is the one thing the nightly cannot push itself:
// the mechanical apply writes it into the working tree as usual, preprocessing WITHHOLDS
// it from the commit (the Action's GITHUB_TOKEN may not write `.github/workflows/`, and
// the refusal would reject the whole ref), and baselining's AGENT stage lands it over MCP
// — a credential that does hold the `workflows` permission. That is
// `withheldWorkflowPaths` in the baselining worker plus PRINCIPLES.md of its task.md; this record
// declares WHAT to vendor and stays out of how.
//
// STANDING, NOT TRANSITIONAL — the same shape (and the same reason) as
// `static-site-vendoring`. There is no old shape to move off: this workflow never
// existed anywhere else, so `legacyPresent` is false everywhere by construction — the
// record exists to keep the copy current, forever, applied from the fresh canon clone
// each member's baselining fetches (where every record loads regardless of age). If a
// general "keep a pack's vendored set current" mechanism is ever built, this record is
// one of the two it replaces.
//
// THE GATE is the repo's own declaration of the sheepdog pack — not the presence of the
// workflow it materializes. That is deliberate and different from the two other
// vendoring records, which gate on a file adoption already put there: declaring the
// enforcer pack IS the adoption here, so the first cycle after the declaration installs
// the workflow, with no separate bootstrap step. Claudinite itself does not declare
// sheepdog, so the canon never self-applies.
import { canonicalPackId } from '../../../../engine/pack_loader/renamed-packs.mjs';

// BOTH settings-file names (#1252). This record is gated on a PACK's version, so it
// can still be in a member's gap long after that member renamed its settings file —
// and a read that only knew the name in use when this landed would find nothing and
// silently never apply.
const DECLARATIONS = ['.claudinite-settings.json', '.claudinite-checks.json'];
const readDeclaration = async (read) => {
  for (const name of DECLARATIONS) {
    const raw = await read(name);
    if (raw != null) return raw;
  }
  return null;
};
// Matched through the rename map: the pack was called `sheepdog` when this record
// landed, and an enforcer's declaration converges onto the current id on its own
// schedule.
const PACK = 'claudinite-fleet-sheepdog';

export default {
  id: 'sheepdog-fleet-baseline',
  landed: '2026-08-05',
  version: 1,
  summary: 'sheepdog fleet-baseline workflow kept byte-current in the enforcer repo own .github/',

  // The gate is ONE question — does this repo declare the sheepdog pack. A `packs` entry
  // is either the bare id or `{ id, ... }`, both legal in a declaration, so both are
  // matched. An unreadable or unparsable declaration means "not an enforcer as far as this
  // record can tell": skip, never guess a repo into hosting a fleet-wide lever.
  //
  // Whether the member can deliver a workflow file is not asked here — that belongs to the
  // machinery, not to each record that ships one: `applyMaterializations` skips a
  // `.github/workflows/` dest unless the running caller announced (WITHHOLD_CAPABLE_ENV)
  // that it can withhold the path from its push.
  appliesTo: async (read) => {
    const text = await readDeclaration(read);
    if (!text) return false;
    let cfg;
    try { cfg = JSON.parse(text); } catch { return false; }
    return (Array.isArray(cfg?.packs) ? cfg.packs : [])
      .some((e) => canonicalPackId(typeof e === 'string' ? e : e?.id) === PACK);
  },

  materialize: [
    { template: 'packs/sheepdog/stubs/workflows/fleet-baseline.yml', dest: '.github/workflows/fleet-baseline.yml' },
  ],

  // Nothing to leave behind: this record exists to keep one copy current, not to move a
  // repo off an older shape.
  legacyPresent: async () => false,
};

// MARKING A MEMBER'S WORK-LIST ISSUE (protocol.mjs's `MARK`, docs/PRINCIPLES.md
// PRINCIPLES.md). The enforcer's two halves — the weekly scan and the hand-forced request
// — each converge one issue per member, and both hand it here: the issue carries
// the mark, its body names the member task in a `Task:` field, and the member's own
// hourly scheduler run adopts it. Nothing dispatches a wake for it any more.
//
// Three things this owns that neither caller should re-derive:
//
//  - THE LABEL EXISTS FIRST. Applying a label GitHub does not know 422s, and a
//    refused mark is a work list nobody ever runs — so the mark is created in the
//    member before it is applied, from the engine's own definition of it rather
//    than a second copy of its colour and prose.
//  - THE MACHINE BLOCK SURVIVES A REWRITE. A repeated force rewrites the body; once
//    the member has adopted the issue, part of that body is the machine's (the
//    block adoption appended). Rewriting the human half and re-attaching the block
//    is what keeps a re-forced ask from erasing the item it is asking for.
//  - A CHANGED ASK RE-ASKS. Clearing the status is the one re-ask lever (PRINCIPLES.md), so
//    a body that actually changed clears whatever status stands — a parked or
//    finished run of the OLD list must not be what silences the new one.
import { ensureLabel } from '../../fleet-api.mjs';
import {
  ORIGIN_AD_HOC, QUEUE_LABELS, statusOf, spellingsOf, machineBlockOf, withMachineBlock,
} from '../../../claudinite-tasks/shared-code/work-items.mjs';
import { MARK, withTargeting } from './protocol.mjs';

// The engine's own definition of the mark — never a second copy of its colour and
// description, which would drift the moment either side is edited.
const MARK_LABEL = QUEUE_LABELS.find((l) => l.name === ORIGIN_AD_HOC);

export async function ensureMark(gh, fullName) {
  await ensureLabel(gh, fullName, MARK, { color: MARK_LABEL.color, description: MARK_LABEL.description });
}

// The body to write for a work list: the targeting fields, the caller's list, and —
// where the member has already adopted this issue — the machine block it wrote,
// re-attached unchanged.
export const markedBody = (body, existing = null, { blockedBy = null } = {}) => {
  const block = existing ? machineBlockOf(existing.body) : null;
  const human = withTargeting(body, { blockedBy });
  return block === null ? human : withMachineBlock(human, block);
};

// Bring an EXISTING work-list issue to the marked shape: the mark applied (an issue
// opened before this fold has none), the body rewritten only where it differs, and
// the status cleared when it did — the re-ask. Returns whether anything was written.
export async function remarkWorkList(gh, fullName, existing, body) {
  await ensureMark(gh, fullName);
  const labels = (existing.labels ?? []).map((l) => l.name ?? l);
  if (!labels.includes(MARK)) {
    await gh(`/repos/${fullName}/issues/${existing.number}/labels`, { method: 'POST', body: { labels: [MARK] } });
  }
  if (existing.body === body) return false;
  await gh(`/repos/${fullName}/issues/${existing.number}`, { method: 'PATCH', body: { body } });
  const status = statusOf({ labels });
  if (status) {
    for (const spelling of spellingsOf(status)) {
      await gh(`/repos/${fullName}/issues/${existing.number}/labels/${encodeURIComponent(spelling)}`, { method: 'DELETE' });
    }
  }
  return true;
};

// The member's other open work list, if it has one — what a newly marked list waits
// on, so two lists in one member run one after the other rather than putting two
// sessions on one declaration.
export const otherOpenWorkList = (open, title) => open.find((i) => i.title !== title)?.number ?? null;

